rule InitBlockII initially false {
if ( EcuMode == MDG_EcuMode.ECU_STARTUP_ONE && EcuM_WakeupSource ==
ECUM_WKSTATUS_VALIDATED) {
actionlist InitBlockIITrueActions
} else {
actionlist InitBlockIIFalseActions
}
